      explicarFamilia: 'Esse remedio nao mata a infeccao, ele so deixa a crianca mais confortavel enquanto o corpo trabalha. Por isso a gente da quando ela esta incomodada, e nao so porque o termometro marcou um numero. Eu vou anotar a quantidade certa pelo peso dela e a hora de cada dose, e a senhora nao precisa alternar com outro remedio.',
      relacionado: ['febre', 'hipertermia_vs_febre', 'dose_por_peso', 'analgesia_crianca', 'convulsao_febril', 'inflamacao'],
      fontes: [ { nome: 'Harriet Lane Handbook, 23a ed.', ano: 2023 }, { nome: 'SBP - Tratado de Pediatria', ano: 2022 }, { nome: 'Nelson Textbook of Pediatrics, 21a ed.', ano: 2020 } ]
